        $json=$this->json($profile);$sha=hash('sha256',$json);$id=Identifier::generate();
        $this->pdo->beginTransaction();try{$this->pdo->prepare("INSERT INTO municipal_project_profiles(id,organisation_id,project_id,application_type,municipality,profile_snapshot,profile_sha256,created_by,updated_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:application,:municipality,:snapshot,:sha,UNHEX(:created),UNHEX(:updated)) ON DUPLICATE KEY UPDATE application_type=VALUES(application_type),municipality=VALUES(municipality),profile_snapshot=VALUES(profile_snapshot),profile_sha256=VALUES(profile_sha256),version=version+1,updated_by=VALUES(updated_by)")->execute(['id'=>$id,'o'=>$o,'p'=>$p,'application'=>$profile['applicationType'],'municipality'=>$profile['municipality'],'snapshot'=>$json,'sha'=>$sha,'created'=>$u,'updated'=>$u]);(new AuditService($this->pdo))->append($o,$u,'municipal_profile.saved','municipal_project_profile',$p,['projectId'=>$p,'applicationType'=>$profile['applicationType'],'profileSha256'=>$sha]);$this->pdo->commit();}catch(Throwable$e){$this->rollback();throw$e;}return$this->profile($o,$u,$p);
    }

    /** @return array<string,mixed> */
