    }

    /** @return array<string,mixed> */
    public function materialiseAssessment(string$o,string$u,string$a):array
    {
        $this->member($o,$u);$assessment=$this->assessment($o,$a);$p=$assessment['projectId'];$this->profile($o,$u,$p);
        $exists=$this->pdo->prepare('SELECT COUNT(*) FROM municipal_professional_routes WHERE organisation_id=UNHEX(:o) AND assessment_id=UNHEX(:a)');$exists->execute(['o'=>$o,'a'=>$a]);if((int)$exists->fetchColumn()>0)return$this->workflow($o,$u,$a);
        $this->pdo->beginTransaction();try{
            $findingInsert=$this->pdo->prepare("INSERT INTO municipal_readiness_findings(id,organisation_id,project_id,assessment_id,finding_key,category,severity,title,explanation,source_reference,responsible_role,status,human_approval_required) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:a),:finding_key,:category,:severity,:title,:explanation,:source,:role,'open',1)");
            foreach(($assessment['snapshot']['checks']??[])as$check){if(!is_array($check)||!in_array($check['status']??null,['missing','requires_professional_review'],true))continue;$severity=$check['status']==='missing'?'blocker':'warning';$key=$this->slug((string)($check['id']??$check['label']??'finding'));$findingInsert->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'a'=>$a,'finding_key'=>$key,'category'=>$this->bounded((string)($check['category']??'manual_verification'),100),'severity'=>$severity,'title'=>$this->bounded((string)($check['label']??'Manual verification required'),220),'explanation'=>$this->bounded(($severity==='blocker'?'Required readiness evidence is missing: ':'Professional verification remains open: ').(string)($check['label']??$key),4000),'source'=>$this->bounded((string)($check['evidenceSource']??'Manual verification required'),1000),'role'=>$this->bounded((string)($check['owner']??'lead_professional'),100)]);}
            $routeInsert=$this->pdo->prepare("INSERT INTO municipal_professional_routes(id,organisation_id,project_id,assessment_id,route_key,discipline,trigger_reason,severity,required_before_issue,supervising_professional_required,status) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:a),:route_key,:discipline,:reason,:severity,1,:supervision,'required')");
            foreach(($assessment['snapshot']['professionalRouting']??[])as$route){if(!is_array($route)||($route['status']??null)!=='required'||($route['professionalApprovalRequired']??true)!==true)continue;$discipline=$this->bounded((string)($route['discipline']??'lead_professional'),100);$routeInsert->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'a'=>$a,'route_key'=>$this->slug($discipline),'discipline'=>$discipline,'reason'=>$this->bounded((string)($route['reason']??'Professional readiness review required.'),4000),'severity'=>($route['teamStatus']??null)==='missing'?'blocker':'warning','supervision'=>($route['supervisingProfessionalRequired']??false)?1:0]);}
            (new AuditService($this->pdo))->append($o,$u,'municipal_readiness.workflow_materialised','municipal_readiness_assessment',$a,['projectId'=>$p]);$this->pdo->commit();
        }catch(Throwable$e){$this->rollback();throw$e;}return$this->workflow($o,$u,$a);
    }

    /** @return array<string,mixed> */
