        $route=$this->route($o,$a,$id);if($route['supervisingProfessionalRequired']&&$supervisor===null)throw new MunicipalReadinessException('municipal_route_supervisor_required');$s=$this->pdo->prepare("UPDATE municipal_professional_routes SET assigned_user_id=UNHEX(:assigned),supervisor_user_id=UNHEX(:supervisor),status='assigned',signoff_declaration=NULL,signed_off_by=NULL,signed_off_at=NULL,supervisor_declaration=NULL,supervisor_signed_off_by=NULL,supervisor_signed_off_at=NULL WHERE id=UNHEX(:id) AND assessment_id=UNHEX(:a) AND organisation_id=UNHEX(:o)");$s->execute(['assigned'=>$assigned,'supervisor'=>$supervisor,'id'=>$id,'a'=>$a,'o'=>$o]);if($s->rowCount()!==1)throw new MunicipalReadinessException('municipal_route_not_found');(new AuditService($this->pdo))->append($o,$u,'municipal_readiness.route_assigned','municipal_professional_route',$id,['assessmentId'=>$a,'assignedUserId'=>$assigned,'supervisorUserId'=>$supervisor]);return$this->workflow($o,$u,$a);
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function signOffRoute(string$o,string$u,string$r,string$a,string$id,array$input):array
    {
        $this->writer($o,$u,$r);if(($input['humanConfirmed']??false)!==true)throw new MunicipalReadinessException('municipal_route_signoff_confirmation_required');$route=$this->route($o,$a,$id);$declaration=$this->text($input['declaration']??($input['supervisorDeclaration']??null),2000,'municipal_route_signoff_declaration_required');$primary=$route['assignedUserId']===$u;$supervisor=$route['supervisorUserId']===$u&&($input['supervisorConfirmed']??false)===true;if(!$primary&&!$supervisor)throw new MunicipalReadinessException('municipal_route_signoff_actor_denied');
        if($primary){$this->pdo->prepare("UPDATE municipal_professional_routes SET status='signed_off',signoff_declaration=:declaration,signed_off_by=UNHEX(:u),signed_off_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND assessment_id=UNHEX(:a)")->execute(['declaration'=>$declaration,'u'=>$u,'id'=>$id,'o'=>$o,'a'=>$a]);}
        if($supervisor){$supervisorDeclaration=$this->text($input['supervisorDeclaration']??null,2000,'municipal_route_supervisor_declaration_required');$this->pdo->prepare("UPDATE municipal_professional_routes SET supervisor_declaration=:declaration,supervisor_signed_off_by=UNHEX(:u),supervisor_signed_off_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND assessment_id=UNHEX(:a)")->execute(['declaration'=>$supervisorDeclaration,'u'=>$u,'id'=>$id,'o'=>$o,'a'=>$a]);}
        (new AuditService($this->pdo))->append($o,$u,$supervisor?'municipal_readiness.route_supervisor_signed_off':'municipal_readiness.route_signed_off','municipal_professional_route',$id,['assessmentId'=>$a]);return$this->workflow($o,$u,$a);
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function issuePack(string$o,string$u,string$r,string$a,array$input):array
    {
        $this->writer($o,$u,$r);if(($input['humanConfirmed']??false)!==true)throw new MunicipalReadinessException('municipal_pack_issue_confirmation_required');$reason=$this->text($input['issueReason']??null,1000,'municipal_pack_issue_reason_required');$principal=$this->principal($input['principalProfessional']??null);$workflow=$this->workflow($o,$u,$a);$profile=$workflow['profile'];$facts=['matrixVerified'=>($workflow['assessment']['matrix']['status']??null)==='verified','professionalReviewApproved'=>$workflow['professionalReview']!==null,'authorityConfirmed'=>($profile['ownershipConfirmed']??false)===true||($profile['agentAuthorised']??false)===true];$gate=$this->policy->issueGate($facts,$workflow['findings'],$workflow['professionalRoutes']);if(!$gate['eligible'])throw new MunicipalReadinessException($gate['failures'][0]);
        $existing=$this->packForAssessment($o,$a);if($existing!==null)throw new MunicipalReadinessException('municipal_pack_assessment_already_issued');$p=$workflow['projectId'];$project=$this->project($o,$p);$packId=Identifier::generate();$issuedAt=(new DateTimeImmutable('now',new DateTimeZone('UTC')))->format('Y-m-d\TH:i:s.u\Z');
        $this->pdo->beginTransaction();try{$lock=$this->pdo->prepare('SELECT COALESCE(MAX(pack_version),0) FROM municipal_submission_packs WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) FOR UPDATE');$lock->execute(['o'=>$o,'p'=>$p]);$version=(int)$lock->fetchColumn()+1;$recordId=(new ProjectRecordService($this->pdo))->issue(new ProjectContext($o,$u,$p,$r),ProjectPhase::MunicipalSubmission,'municipal_readiness','architex_backed_submission_pack','Architex-backed municipal submission pack v'.$version,'issued',['packId'=>$packId,'packVersion'=>$version,'assessmentId'=>$a,'assessmentSha256'=>$workflow['assessmentSha256'],'issueReason'=>$reason,'municipalApproval'=>false,'formalLodgementCreated'=>false],['required'=>true,'humanConfirmed'=>true,'principalProfessional'=>$principal]);$manifestInput=['packId'=>$packId,'packVersion'=>$version,'issuedAt'=>$issuedAt,'principalProfessional'=>$principal,'project'=>['id'=>$p,'projectCode'=>$project['projectCode'],'projectName'=>$project['projectName'],'municipality'=>$project['municipality']],'profile'=>$profile,'readiness'=>['score'=>$workflow['assessment']['overallScore']??null,'status'=>'ready_for_signoff','openFindings'=>$workflow['workflow']['openFindings']],'documents'=>$this->documents($o,$p),'drawings'=>$this->drawings($o,$p),'checklist'=>$workflow['assessment']['checks']??[],'resolutionLog'=>array_values(array_filter($workflow['findings'],static fn(array$f):bool=>$f['status']!=='open')),'signoffRegister'=>$workflow['professionalRoutes'],'sources'=>[['ruleVersion'=>$workflow['assessment']['matrix']['version']??null,'sourceReference'=>$workflow['assessment']['matrix']['sourceReference']??'Manual verification required','effectiveDate'=>$workflow['assessment']['matrix']['effectiveDate']??null]],'assessmentSha256'=>$workflow['assessmentSha256'],'projectRecordId'=>$recordId];$built=$this->policy->buildManifest($manifestInput);$this->pdo->prepare("UPDATE municipal_submission_packs SET status='superseded',superseded_at=U