    /** @return list<array<string,mixed>> */public function listPacks(string$o,string$u,string$p):array{$this->member($o,$u);$this->project($o,$p);$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) FROM municipal_submission_packs WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY pack_version DESC');$s->execute(['o'=>$o,'p'=>$p]);return array_map(fn(string$id):array=>$this->getPack($o,$u,$id),$s->fetchAll(PDO::FETCH_COLUMN));}
    /** @return array<string,mixed> */public function getPack(string$o,string$u,string$id):array{$this->member($o,$u);$id=$this->id($id,'municipal_pack_not_found');$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) project_id,LOWER(HEX(assessment_id)) assessment_id,LOWER(HEX(project_record_id)) project_record_id,pack_version,status,principal_professional,manifest_snapshot,manifest_sha256,LOWER(HEX(issued_by)) issued_by,DATE_FORMAT(issued_at,'%Y-%m-%dT%H:%i:%s.%fZ') issued_at,DATE_FORMAT(superseded_at,'%Y-%m-%dT%H:%i:%s.%fZ') superseded_at FROM municipal_submission_packs WHERE organisation_id=UNHEX(:o) AND id=UNHEX(:id)");$s->execute(['o'=>$o,'id'=>$id]);$row=$s->fetch();if(!is_array($row))throw new MunicipalReadinessException('municipal_pack_not_found');if(!hash_equals((string)$row['manifest_sha256'],hash('sha256',(string)$row['manifest_snapshot'])))throw new MunicipalReadinessException('municipal_pack_integrity_failed');return['id'=>$row['id'],'projectId'=>$row['project_id'],'assessmentId'=>$row['assessment_id'],'projectRecordId'=>$row['project_record_id'],'packVersion'=>(int)$row['pack_version'],'status'=>$row['status'],'principalProfessional'=>$this->decode((string)$row['principal_professional']),'manifest'=>$this->decode((string)$row['manifest_snapshot']),'manifestSha256'=>$row['manifest_sha256'],'issuedBy'=>$row['issued_by'],'issuedAt'=>$row['issued_at'],'supersededAt'=>$row['superseded_at']];}

    /** @return array{projectId:string,snapshotSha256:string,snapshot:array<string,mixed>} */private function assessment(string$o,string$a):array{$a=$this->id($a,'municipal_readiness_not_found');$s=$this->pdo->prepare('SELECT LOWER(HEX(project_id)) project_id,assessment_snapshot,snapshot_sha256 FROM municipal_readiness_assessments WHERE organisation_id=UNHEX(:o) AND id=UNHEX(:a)');$s->execute(['o'=>$o,'a'=>$a]);$row=$s->fetch();if(!is_array($row))throw new MunicipalReadinessException('municipal_readiness_not_found');$snapshot=$this->decode((string)$row['assessment_snapshot']);if(!hash_equals((string)$row['snapshot_sha256'],hash('sha256',$this->json($snapshot))))throw new MunicipalReadinessException('municipal_readiness_integrity_failed');return['projectId'=>(string)$row['project_id'],'snapshotSha256'=>(string)$row['snapshot_sha256'],'snapshot'=>$snapshot];}
    /** @return array<string,mixed> */private function project(string$o,string$p):array{$p=$this->id($p,'municipal_project_not_found');$s=$this->pdo->prepare('SELECT project_code projectCode,project_name projectName,municipality FROM projects WHERE organisation_id=UNHEX(:o) AND id=UNHEX(:p)');$s->execute(['o'=>$o,'p'=>$p]);$row=$s->fetch();if(!is_array($row))throw new MunicipalReadinessException('municipal_project_not_found');return$row;}
    /** @return list<array<string,mixed>> */private function findings(string$o,string$a):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,finding_key findingKey,category,severity,title,explanation,source_reference sourceReference,responsible_role responsibleRole,status,human_approval_required humanApprovalRequired,resolution_reason resolutionReason,LOWER(HEX(resolved_by)) resolvedBy,DATE_FORMAT(resolved_at,'%Y-%m-%dT%H:%i:%s.%fZ') resolvedAt FROM municipal_readiness_findings WHERE organisation_id=UNHEX(:o) AND assessment_id=UNHEX(:a) ORDER BY FIELD(severity,'blocker','warning','advisory'),created_at,id");$s->execute(['o'=>$o,'a'=>$a]);$rows=$s->fetchAll();foreach($rows as&$row)$row['humanApprovalRequired']=(bool)$row['humanApprovalRequired'];return$rows;}
    /** @return list<array<string,mixed>> */private function routes(string$o,string$a):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,route_key routeKey,discipline,trigger_reason reason,severity,required_before_issue requiredBeforeIssue,supervising_professional_required supervisingProfessionalRequired,LOWER(HEX(assigned_user_id)) assignedUserId,LOWER(HEX(supervisor_user_id)) supervisorUserId,status,signoff_declaration signoffDeclaration,LOWER(HEX(signed_off_by)) signedOffBy,DATE_FORMAT(signed_off_at,'%Y-%m-%dT%H:%i:%s.%fZ') signedOffAt,supervisor_declaration supervisorDeclaration,LOWER(HEX(supervisor_signed_off_by)) supervisorSignedOffBy,DATE_FORMAT(supervisor_signed_off_at,'%Y-%m-%dT%H:%i:%s.%fZ') supervisorSignedOffAt FROM municipal_professional_routes WHERE organisation_id=UNHEX(:o) AND assessment_id=UNHEX(:a) ORDER BY created_at,id");$s->execute(['o'=>$o,'a'=>$a]);$rows=$s->fetchAll();foreach($rows as&$row){$row['requiredBeforeIssue']=(bool)$row['requiredBeforeIssue'];$row['supervisingProfessionalRequired']=(bool)$row['supervisingProfessionalRequired'];$row['supervisorSignedOff']=$row['supervisorSignedOffAt']!==null;}return$rows;}
    /** @return array<string,mixed> */private function route(string$o,string$a,string$id):array{$id=$this->id($id,'municipal_route_not_found');foreach($this->routes($o,$a)as$route)if($route['id']===$id)return$route;throw new MunicipalReadinessException('municipal_route_not_found');}
    /** @return array<string,mixed>|null */private function review(string$o,string$a):?array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,decision,reason,LOWER(HEX(reviewed_by)) reviewedBy,DATE_FORMAT(reviewed_at,'%Y-%m-%dT%H:%i:%s.%fZ') reviewedAt FROM municipal_readiness_reviews WHERE organisation_id=UNHEX(:o) AND assessment_id=UNHEX(:a) AND decision='approved_for_professional_submission_review'");$s->execute(['o'=>$o,'a'=>$a]);$row=$s->fetch();return is_array($row)?$row:null;}
    /** @return array<string,mixed>|null */private function packForAssessment(string$o,string$a):?array{$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) FROM municipal_submission_packs WHERE organisation_id=UNHEX(:o) AND assessment_id=UNHEX(:a)');$s->execute(['o'=>$o,'a'=>$a]);$id=$s->fetchColumn();return is_string($id)?$this->packRow($o,$id):null;}
    /** @return array<string,mixed> */private function packRow(string$o,string$id):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,pack_version packVersion,status,manifest_sha256 manifestSha256 FROM municipal_submission_packs WHERE organisation_id=UNHEX(:o) AND id=UNHEX(:id)");$s->execute(['o'=>$o,'id'=>$id]);$row=$s->fetch();if(!is_array($row))throw new MunicipalReadinessException('municipal_pack_not_found');$row['packVersion']=(int)$row['packVersion'];return$row;}
    /** @return list<array<string,mixed>> */private function documents(string$o,string$p):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(d.id)) id,d.title,d.document_type documentType,d.discipline,r.revision_code revision,r.status,r.issue_purpose issuePurpose,r.audit_hash sha256,DATE_FORMAT(COALESCE(r.issued_at,r.approved_at,r.created_at),'%Y-%m-%dT%H:%i:%s.%fZ') date FROM controlled_documents d JOIN document_revisions r ON r.id=d.current_revision_id AND r.organisation_id=d.organisation_id WHERE d.organisation_id=UNHEX(:o) AND d.project_id=UNHEX(:p) AND r.status IN ('approved','issued') ORDER BY d.title");$s->execute(['o'=>$o,'p'=>$p]);return$s->fetchAll();}
    /** @return list<array<string,mixed>> */private function drawings(string$o,string$p):array{$s=$this->pdo->prepare("SELECT e.drawing_number number,e.title,e.discipline,e.sheet_type sheetType,r.revision_code revision,r.audit_hash sha256,DATE_FORMAT(COALESCE(r.issued_at,r.approved_at,r.created_at),'%Y-%m-%dT%H:%i:%s.%fZ') date FROM drawing_register_entries e JOIN document_revisions r ON r.id=e.revision_id AND r.organisation_id=e.organisation_id WHERE e.organisation_id=UNHEX(:o) AND e.project_id=UNHEX(:p) AND e.status='issued' AND e.issue_purpose='for_municipal_submission' ORDER BY e.drawing_number");$s->execute(['o'=>$o,'p'=>$p]);return$s->fetchAll();}
    /** @return array{name:string,role:string,registration:string} */private function principal(mixed$v):array{if(!is_array($v))throw new MunicipalReadinessException('municipal_pack_principal_required');return['name'=>$this->text($v['name']??null,180,'municipal_pack_principal_required'),'role'=>$this->text($v['role']??null,100,'municipal_pack_principal_required'),'registration'=>$this->text($v['registration']??null,120,'municipal_pack_principal_required')];}
    private function inbox(string$o,string$p,string$id,int$version,string$sha):void{$payload=$this->json(['packId'=>$id,'packVersion'=>$version,'manifestSha256'=>$sha,'municipalApproval'=>false]);$this->pdo->prepare("INSERT INTO workflow_events(id,organisation_id,project_id,event_type,priority,source_module,payload) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),'municipal_submission_pack_issued','medium','municipal_readiness',:payload)")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'payload'=>$payload]);$this->pdo->prepare("INSERT INTO inbox_items(id,organisation_id,project_id,assigned_role,event_type,title,detail,priority,status,payload) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),'lead_professional','municipal_submission_pack_issued',:title,:detail,'medium','open',:payload)")->execute(['id'=>Identifier::generate(),'o'=>$o,'p'=>$p,'title'=>'Architex-backed submission pack v'.$version.' issued','detail'=>'Immutable professional-side pack issued. Municipal approval and formal lodgement remain external.','payload'=>$payload]);}
    private function member(string$o,string$u):string{$s=$this->pdo->prepare("SELECT role FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$this->id($o,'municipal_readiness_permission_denied'),'u'=>$this->id($u,'municipal_readiness_permission_denied')]);$role=$s->fetchColumn();if(!is_string($role))throw new MunicipalReadinessException('municipal_readiness_permission_denied');return$role;}
    private function writer(string$o,string$u,string$r):void
    {
        $actual=$this->member($o,$u);
        if($actual!==$r||!in_array($actual,['owner','admin','member'],true))throw new MunicipalReadinessException('municipal_readiness_role_denied');
        $statement=$this->pdo->prepare('SELECT role_key FROM registration_profiles WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u)');
        $statement->execute(['o'=>$o,'u'=>$u]);
        if(in_array($statement->fetchColumn(),['client','contractor'],true))throw new MunicipalReadinessException('municipal_readiness_role_denied');
    }
    private function id(mixed$v,string$e):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new MunicipalReadinessException($e);return strtolower($v);}
    private function text(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if($v===''||mb_strlen($v)>$m)throw new MunicipalReadinessException($e);return$v;}
    private function bounded(string$v,int$m):string{$v=trim($v);return mb_strlen($v)>$m?mb_substr($v,0,$m):$v;}
    private function slug(string$v):string{$v=strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',$v),'-'));return$v===''?'manual-verification':substr($v,0,160);}
    private function key(string$v):string{return strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',$v),'-'));}
    /** @param array<mixed> $v */private function json(array$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_PRESERVE_ZERO_FRACTION);}
    /** @return array<string,mixed> */private function decode(string$v):array{$decoded=json_decode($v,true,128,JSON_THROW_ON_ERROR);if(!is_array($decoded))throw new MunicipalReadinessException('municipal_readiness_integrity_failed');return$decoded;}
    private function rollback():void{if($this->pdo->inTransaction())$this->pdo->rollBack();}
}
